<?php require_once __DIR__.'/../includes/db.php'; require_once __DIR__.'/../includes/auth.php'; require_login(); $uid=$_SESSION['user']['id']; $stmt=$mysqli->prepare("SELECT * FROM bookings WHERE user_id=? AND status IN ('paid','entered') ORDER BY id DESC LIMIT 1"); $stmt->bind_param('i',$uid); $stmt->execute(); $active=$stmt->get_result()->fetch_assoc(); $available=$mysqli->query("SELECT COUNT(*) c FROM slots WHERE status='available'")->fetch_assoc()['c']; $page_title='Dashboard'; require __DIR__.'/../includes/header.php'; ?>
<h2>Hello, <?=e($_SESSION['user']['name'])?>!</h2><div class="row g-4 mt-1"><div class="col-md-4"><div class="card stat-card p-4 shadow-sm"><small class="text-muted">Available slots</small><strong class="display-6 text-primary"><?=$available?></strong><a href="slots.php">View slots</a></div></div><div class="col-md-8"><div class="card stat-card p-4 shadow-sm"><h5>Current booking</h5><?php if($active): ?><p class="mb-1"><b><?=e($active['booking_code'])?></b> · <?=e($active['status'])?></p><p class="text-muted mb-2">From <?=date('d M, h:i A',strtotime($active['start_time']))?> to <?=date('d M, h:i A',strtotime($active['end_time']))?></p><a class="btn btn-primary btn-sm" href="booking.php?id=<?=$active['id']?>">View QR & booking</a><?php else: ?><p class="text-muted">No active booking. Reserve a spot before you leave.</p><a class="btn btn-primary btn-sm" href="slots.php">Book now</a><?php endif; ?></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
